function extractJson(text) {
  let s = text.trim();
  if (s.startsWith("```")) {
    s = s.replace(/^```[a-zA-Z]*\s*/, "").replace(/```$/, "").trim();
  }
  try {
    return JSON.parse(s);
  } catch {
    return null;
  }
}

