  const errors = [];
  for (const [field, type] of Object.entries(schema)) {
    if (!(field in obj)) {
      errors.push(field + ": missing");
      continue;
    }
    if (typeof obj[field] !== type) errors.push(field + ": expected " + type);
  }
  return errors;
}

