import json

def parse_with_retries(outputs, required, max_attempts):
    attempts = 0
    for text in outputs[:max_attempts]:
        attempts += 1
        try:
            obj = json.loads(text)
        except ValueError:
            continue
        if isinstance(obj, dict) and all(k in obj for k in required):
            return {"attempts": attempts, "value": obj}
    return {"attempts": attempts, "value": None}
